<template>
  <div class="container-fluid px-0">
    <div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-3">
      <div>
        <h4 class="mb-1">{{ tabs.find(t=>t.id===activeTab)?.label }}</h4>
        <div class="text-muted small">Enterprise pharmacy operations</div>
      </div>
      <button class="btn btn-outline-primary btn-sm" @click="loadAll" :disabled="loading"><i class="bi bi-arrow-clockwise me-1"></i>Refresh</button>
    </div>

    <div class="row g-3 mb-3">
      <div v-for="card in summaryCards" :key="card.label" class="col-6 col-md-3 col-xl">
        <div class="card border-0 shadow-sm h-100"><div class="card-body py-3">
          <div class="text-muted small">{{ card.label }}</div><div class="fs-4 fw-semibold">{{ overview[card.key] ?? 0 }}</div>
        </div></div>
      </div>
    </div>


    <!-- 5.1 Procurement -->
    <section v-if="activeTab==='procurement'" class="row g-3">
      <div class="col-xl-4"><div class="card h-100"><div class="card-header fw-semibold">Create supplier quotation</div><div class="card-body">
        <form @submit.prevent="createQuotation" class="vstack gap-2">
          <label class="form-label mb-0">Supplier</label><select v-model.number="quote.supplier_id" class="form-select" required><option value="">Select supplier</option><option v-for="x in lookups.suppliers" :key="x.id" :value="x.id">{{ x.name }}</option></select>
          <label class="form-label mb-0">Medicine</label><select v-model.number="quote.medicine_id" class="form-select" required><option value="">Select medicine</option><option v-for="x in lookups.medicines" :key="x.id" :value="x.id">{{ x.name }} {{ x.strength||'' }}</option></select>
          <div class="row g-2"><div class="col"><label class="form-label mb-0">Quantity</label><input v-model.number="quote.quantity" type="number" min="1" class="form-control" required></div><div class="col"><label class="form-label mb-0">Unit price</label><input v-model.number="quote.unit_price" type="number" min="0" step="0.01" class="form-control" required></div></div>
          <div class="row g-2"><div class="col"><label class="form-label mb-0">Lead days</label><input v-model.number="quote.lead_days" type="number" min="0" class="form-control"></div><div class="col"><label class="form-label mb-0">Tax %</label><input v-model.number="quote.tax_percent" type="number" min="0" max="100" step="0.01" class="form-control"></div></div>
          <label class="form-label mb-0">Valid until</label><input v-model="quote.valid_until" type="date" class="form-control">
          <button class="btn btn-primary" :disabled="saving">Submit quotation</button>
        </form>
      </div></div></div>
      <div class="col-xl-8"><div class="card"><div class="card-header fw-semibold">Supplier quotations</div><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Quote</th><th>Supplier</th><th>Date</th><th>Total</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody>
        <tr v-for="q in quotations" :key="q.id"><td>{{ q.quote_no }}</td><td>{{ q.supplier_name }}</td><td>{{ q.quote_date }}</td><td>{{ money(q.total) }}</td><td><span class="badge text-bg-light">{{ q.status }}</span></td><td class="text-end text-nowrap"><template v-if="q.status==='submitted'"><button class="btn btn-sm btn-outline-primary me-1" @click="reviewQuote(q,'accepted')">Accept</button><button class="btn btn-sm btn-outline-danger" @click="reviewQuote(q,'rejected')">Reject</button></template><button v-if="q.status==='accepted'" class="btn btn-sm btn-primary" @click="convertQuote(q)">Convert to PO</button></td></tr>
        <tr v-if="!quotations.length"><td colspan="6" class="text-center text-muted py-4">No quotations found.</td></tr>
      </tbody></table></div></div>
        <div class="card mt-3"><div class="card-header fw-semibold">Supplier price comparison by medicine</div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Medicine</th><th>Supplier</th><th>Unit price</th><th>Qty</th><th>Lead days</th><th>Quote</th></tr></thead><tbody><tr v-for="i in quoteComparisons" :key="i.id"><td>{{ i.medicine_name }} {{ i.strength||'' }}</td><td>{{ i.supplier_name }}</td><td>{{ money(i.unit_price) }}</td><td>{{ i.quantity }}</td><td>{{ i.lead_days }}</td><td>{{ i.quote_no }} ({{ i.status }})</td></tr><tr v-if="!quoteComparisons.length"><td colspan="6" class="text-center text-muted">No comparable supplier quotes.</td></tr></tbody></table></div></div>
      </div>
    </section>

    <!-- 5.1 Warehouse -->
    <section v-else-if="activeTab==='warehouse'" class="row g-3">
      <div class="col-lg-4"><div class="card"><div class="card-header fw-semibold">Add warehouse location</div><div class="card-body"><form class="vstack gap-2" @submit.prevent="createLocation"><input v-model="location.code" class="form-control" placeholder="Code e.g. RACK-C" required><input v-model="location.name" class="form-control" placeholder="Location name" required><select v-model="location.location_type" class="form-select"><option value="zone">Zone</option><option value="rack">Rack</option><option value="shelf">Shelf</option><option value="bin">Bin</option></select><button class="btn btn-primary">Save location</button></form></div></div>
        <div class="card mt-3"><div class="card-header fw-semibold">Allocate batch to bin</div><div class="card-body"><form class="vstack gap-2" @submit.prevent="allocateBatch"><select v-model.number="allocation.batch_id" class="form-select" required><option value="">Select batch</option><option v-for="b in lookups.batches" :key="b.id" :value="b.id">{{ b.medicine_name }} · {{ b.batch_no||('#'+b.id) }} · Qty {{ b.quantity }}</option></select><select v-model.number="allocation.location_id" class="form-select" required><option value="">Select location</option><option v-for="l in locations" :key="l.id" :value="l.id">{{ l.code }} – {{ l.name }}</option></select><input v-model.number="allocation.quantity" type="number" min="0" class="form-control" placeholder="Quantity" required><button class="btn btn-primary">Allocate</button></form></div></div>
      </div>
      <div class="col-lg-8"><div class="card mb-3"><div class="card-header fw-semibold">Warehouse locations</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Code</th><th>Name</th><th>Type</th></tr></thead><tbody><tr v-for="l in locations" :key="l.id"><td>{{ l.code }}</td><td>{{ l.name }}</td><td>{{ l.location_type }}</td></tr><tr v-if="!locations.length"><td colspan="3" class="text-center text-muted">No locations yet.</td></tr></tbody></table></div></div>
        <div class="card"><div class="card-header fw-semibold">Physical stock count</div><div class="card-body"><form class="row g-2" @submit.prevent="createStockCount"><div class="col-md-5"><select v-model.number="count.batch_id" class="form-select" required><option value="">Select batch</option><option v-for="b in lookups.batches" :key="b.id" :value="b.id">{{ b.medicine_name }} · {{ b.batch_no||('#'+b.id) }} (system {{ b.quantity }})</option></select></div><div class="col-md-3"><input v-model.number="count.counted_quantity" type="number" min="0" class="form-control" placeholder="Counted quantity" required></div><div class="col-md-4"><button class="btn btn-primary w-100">Create count draft</button></div></form></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Count no.</th><th>Date</th><th>Status</th><th class="text-end">Review</th></tr></thead><tbody><tr v-for="c in stockCounts" :key="c.id"><td>{{ c.count_no }}</td><td>{{ c.count_date }}</td><td>{{ c.status }}</td><td class="text-end"><button v-if="['draft','submitted'].includes(c.status)" class="btn btn-sm btn-primary" @click="reviewCount(c,'approve')">Approve</button></td></tr><tr v-if="!stockCounts.length"><td colspan="4" class="text-center text-muted">No stock counts.</td></tr></tbody></table></div></div>
      </div>
    </section>

    <!-- 5.2 Healthcare -->
    <section v-else-if="activeTab==='healthcare'" class="row g-3">
      <div class="col-lg-4"><div class="card"><div class="card-header fw-semibold">Register hospital / clinic / lab</div><div class="card-body"><form class="vstack gap-2" @submit.prevent="saveFacility"><input v-model="facility.name" class="form-control" placeholder="Facility name" required><select v-model="facility.facility_type" class="form-select"><option value="hospital">Hospital</option><option value="clinic">Clinic</option><option value="laboratory">Laboratory</option><option value="other">Other</option></select><input v-model="facility.registration_no" class="form-control" placeholder="Registration number"><input v-model="facility.contact_person" class="form-control" placeholder="Contact person"><input v-model="facility.phone" class="form-control" placeholder="Phone"><input v-model="facility.email" type="email" class="form-control" placeholder="Email"><textarea v-model="facility.address" class="form-control" placeholder="Address"></textarea><button class="btn btn-primary">Save facility</button></form></div></div><div class="card mt-3"><div class="card-header fw-semibold">Submit prescription refill request</div><div class="card-body"><form class="vstack gap-2" @submit.prevent="submitRefill"><input v-model.number="refillRequest.prescription_id" type="number" min="1" class="form-control" placeholder="Original prescription ID" required><select v-model.number="refillRequest.medicine_id" class="form-select" required><option value="">Medicine on prescription</option><option v-for="m in lookups.medicines" :key="m.id" :value="m.id">{{ m.name }} {{ m.strength||'' }}</option></select><input v-model.number="refillRequest.requested_quantity" type="number" min="1" class="form-control" placeholder="Requested quantity" required><input v-model="refillRequest.customer_note" class="form-control" placeholder="Customer note"><button class="btn btn-outline-primary">Submit for pharmacist review</button></form></div></div></div>
      <div class="col-lg-8"><div class="card mb-3"><div class="card-header fw-semibold">Healthcare facilities</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Name</th><th>Type</th><th>Phone</th><th>Registration</th><th></th></tr></thead><tbody><tr v-for="f in facilities" :key="f.id"><td>{{ f.name }}</td><td>{{ f.facility_type }}</td><td>{{ f.phone||'—' }}</td><td>{{ f.registration_no||'—' }}</td><td class="text-end"><button class="btn btn-sm btn-outline-secondary" @click="createFacilityToken(f)">API token</button></td></tr><tr v-if="!facilities.length"><td colspan="5" class="text-center text-muted">No facilities.</td></tr></tbody></table></div></div>
        <div class="card"><div class="card-header fw-semibold">Prescription refill requests</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Request</th><th>Customer</th><th>Medicine</th><th>Qty</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="r in refills" :key="r.id"><td>{{ r.request_no }}</td><td>{{ r.customer_name||'Walk-in' }}</td><td>{{ r.medicine_name }}</td><td>{{ r.requested_quantity }}</td><td>{{ r.status }}</td><td class="text-end"><template v-if="r.status==='pending'"><button class="btn btn-sm btn-primary me-1" @click="reviewRefill(r,'approved')">Approve</button><button class="btn btn-sm btn-outline-danger" @click="reviewRefill(r,'rejected')">Reject</button></template></td></tr><tr v-if="!refills.length"><td colspan="6" class="text-center text-muted">No refill requests.</td></tr></tbody></table></div></div>
      </div>
    </section>

    <!-- 5.3 Compliance -->
    <section v-else-if="activeTab==='compliance'" class="row g-3">
      <div class="col-lg-6"><div class="card mb-3"><div class="card-header fw-semibold">Controlled medicine register</div><div class="card-body"><form class="row g-2" @submit.prevent="recordControlled"><div class="col-md-6"><select v-model.number="controlled.medicine_id" class="form-select" required><option value="">Medicine</option><option v-for="m in lookups.medicines" :key="m.id" :value="m.id">{{ m.name }} {{ m.strength||'' }}</option></select></div><div class="col-md-6"><select v-model.number="controlled.batch_id" class="form-select"><option value="">Batch (optional)</option><option v-for="b in lookups.batches" :key="b.id" :value="b.id">{{ b.medicine_name }} · {{ b.batch_no||b.id }}</option></select></div><div class="col-md-6"><select v-model="controlled.transaction_type" class="form-select"><option>dispense</option><option>purchase</option><option>return</option><option>adjustment</option><option>transfer_in</option><option>transfer_out</option></select></div><div class="col-md-6"><input v-model.number="controlled.quantity_change" type="number" class="form-control" placeholder="Signed quantity (+/-)" required></div><div class="col-12"><input v-model="controlled.reason" class="form-control" placeholder="Reason / source document" required></div><div class="col-12"><button class="btn btn-primary">Record movement</button></div></form><div class="form-text">Enable controlled tracking on a medicine in the medicine register before recording it here.</div></div></div>
        <div class="card mb-3"><div class="card-header fw-semibold">Controlled medicine tracking settings</div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Medicine</th><th>Tracking</th><th class="text-end">Action</th></tr></thead><tbody><tr v-for="m in lookups.medicines" :key="m.id"><td>{{ m.name }} {{ m.strength||'' }}</td><td>{{ m.requires_controlled_tracking ? 'Enabled' : 'Disabled' }}</td><td class="text-end"><button class="btn btn-sm" :class="m.requires_controlled_tracking?'btn-outline-danger':'btn-outline-primary'" @click="setControlled(m)">{{ m.requires_controlled_tracking ? 'Disable' : 'Enable' }}</button></td></tr></tbody></table></div></div>
        <div class="card"><div class="card-header fw-semibold">Medicine recalls</div><div class="card-body"><form class="vstack gap-2" @submit.prevent="createRecall"><input v-model="recall.source" class="form-control" placeholder="Recall source / authority"><select v-model="recall.severity" class="form-select"><option value="notice">Notice</option><option value="warning">Warning</option><option value="urgent">Urgent</option></select><textarea v-model="recall.reason" class="form-control" placeholder="Recall reason" required></textarea><input v-model="recall.issued_on" type="date" class="form-control" required><select v-model.number="recall.medicine_id" class="form-select" required><option value="">Medicine</option><option v-for="m in lookups.medicines" :key="m.id" :value="m.id">{{ m.name }}</option></select><select v-model.number="recall.batch_id" class="form-select"><option value="">All batches / no specific batch</option><option v-for="b in lookups.batches" :key="b.id" :value="b.id">{{ b.medicine_name }} · {{ b.batch_no||b.id }}</option></select><button class="btn btn-danger">Create recall / quarantine batch</button></form></div></div>
      </div>
      <div class="col-lg-6"><div class="card mb-3"><div class="card-header fw-semibold">Controlled medicine history</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Medicine</th><th>Type</th><th>Qty Δ</th><th>Recorded</th></tr></thead><tbody><tr v-for="r in controlledRows" :key="r.id"><td>{{ r.medicine_name }}</td><td>{{ r.transaction_type }}</td><td>{{ r.quantity_change }}</td><td>{{ r.recorded_at }}</td></tr><tr v-if="!controlledRows.length"><td colspan="4" class="text-center text-muted">No register entries.</td></tr></tbody></table></div></div>
        <div class="card"><div class="card-header fw-semibold">Recall register</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Recall</th><th>Severity</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="r in recalls" :key="r.id"><td>{{ r.recall_no }}</td><td>{{ r.severity }}</td><td>{{ r.status }}</td><td class="text-end"><button v-if="r.status!=='closed'" class="btn btn-sm btn-outline-primary" @click="closeRecall(r)">Close</button></td></tr><tr v-if="!recalls.length"><td colspan="4" class="text-center text-muted">No recalls.</td></tr></tbody></table></div></div>
      </div>
    </section>

    <!-- 5.3 insurance -->
    <section v-else-if="activeTab==='insurance'" class="row g-3">
      <div class="col-lg-4"><div class="card"><div class="card-header fw-semibold">Record insurance eligibility check</div><div class="card-body"><form class="vstack gap-2" @submit.prevent="checkEligibility"><select v-model.number="eligibility.provider_id" class="form-select" required><option value="">Insurance provider</option><option v-for="p in lookups.insurance_providers" :key="p.id" :value="p.id">{{ p.name }}</option></select><select v-model.number="eligibility.plan_id" class="form-select"><option value="">Plan (optional)</option><option v-for="p in lookups.insurance_plans.filter(x=>!eligibility.provider_id||x.provider_id===eligibility.provider_id)" :key="p.id" :value="p.id">{{ p.name }}</option></select><select v-model.number="eligibility.customer_id" class="form-select"><option value="">Customer (optional)</option><option v-for="c in lookups.customers" :key="c.id" :value="c.id">{{ c.name }} {{ c.phone||'' }}</option></select><input v-model="eligibility.member_no" class="form-control" placeholder="Member number" required><select v-model="eligibility.result" class="form-select"><option value="eligible">Eligible (manual confirmation)</option><option value="ineligible">Ineligible</option><option value="manual_review">Manual review required</option></select><textarea v-model="eligibility.notes" class="form-control" placeholder="Payer confirmation / notes"></textarea><button class="btn btn-primary">Save eligibility check</button></form><div class="form-text">This records the result confirmed by staff; it does not contact an insurer automatically.</div></div></div></div>
      <div class="col-lg-8"><div class="card"><div class="card-header fw-semibold">Eligibility audit history</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Date</th><th>Provider</th><th>Member</th><th>Customer</th><th>Result</th></tr></thead><tbody><tr v-for="e in eligibilityRows" :key="e.id"><td>{{ e.checked_on }}</td><td>{{ e.provider_name }}</td><td>{{ e.member_no }}</td><td>{{ e.customer_name||'—' }}</td><td>{{ e.result }}</td></tr><tr v-if="!eligibilityRows.length"><td colspan="5" class="text-center text-muted">No eligibility checks.</td></tr></tbody></table></div></div>
        <div class="card mt-3"><div class="card-header fw-semibold">Insurance claim event</div><div class="card-body"><form class="row g-2" @submit.prevent="recordClaimEvent"><div class="col-md-3"><input v-model.number="claimEvent.claim_id" type="number" min="1" class="form-control" placeholder="Claim ID" required></div><div class="col-md-3"><input v-model="claimEvent.event" class="form-control" placeholder="Event / status" required></div><div class="col-md-3"><input v-model="claimEvent.external_reference" class="form-control" placeholder="Payer reference"></div><div class="col-md-3"><input v-model.number="claimEvent.amount" type="number" min="0" step="0.01" class="form-control" placeholder="Amount"></div><div class="col-12"><input v-model="claimEvent.notes" class="form-control" placeholder="Notes"><button class="btn btn-primary mt-2">Add claim event</button></div></form></div></div>
      </div>
    </section>

    <!-- 5.4 engagement -->
    <section v-else-if="activeTab==='engagement'" class="row g-3">
      <div class="col-lg-6"><div class="card mb-3"><div class="card-header fw-semibold">Customer campaign template</div><div class="card-body"><form class="vstack gap-2" @submit.prevent="saveCampaign"><input v-model="campaign.name" class="form-control" placeholder="Campaign name" required><select v-model="campaign.campaign_type" class="form-select"><option value="refill_reminder">Refill reminder</option><option value="loyalty">Loyalty</option><option value="promotion">Promotion</option><option value="general">General</option></select><textarea v-model="campaign.message" class="form-control" rows="3" placeholder="Message template" required></textarea><select v-model="campaign.status" class="form-select"><option value="draft">Draft</option><option value="scheduled">Scheduled</option><option value="active">Active</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select><button class="btn btn-primary">Save campaign</button></form><div class="form-text">Saving a campaign does not send messages. Connect and approve your messaging provider/template before delivery.</div></div></div>
        <div class="card"><div class="card-header fw-semibold">Schedule medicine refill reminder</div><div class="card-body"><form class="vstack gap-2" @submit.prevent="createReminder"><select v-model.number="reminder.customer_id" class="form-select" required><option value="">Customer</option><option v-for="c in lookups.customers" :key="c.id" :value="c.id">{{ c.name }} · {{ c.phone||'' }}</option></select><select v-model.number="reminder.medicine_id" class="form-select" required><option value="">Medicine</option><option v-for="m in lookups.medicines" :key="m.id" :value="m.id">{{ m.name }}</option></select><div class="row g-2"><div class="col"><input v-model="reminder.last_dispensed_on" type="date" class="form-control" required></div><div class="col"><input v-model="reminder.remind_on" type="date" class="form-control" required></div></div><button class="btn btn-primary">Schedule reminder</button></form></div></div></div>
      <div class="col-lg-6"><div class="card mb-3"><div class="card-header fw-semibold">Campaigns <span class="text-muted fw-normal small ms-2">Customer IDs for WhatsApp send are comma-separated</span></div><div class="card-body py-2"><input v-model="campaignCustomerIds" class="form-control form-control-sm" placeholder="Customer IDs, e.g. 4,8,12"></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Name</th><th>Type</th><th>Status</th><th>Delivery</th></tr></thead><tbody><tr v-for="c in campaigns" :key="c.id"><td>{{ c.name }}</td><td>{{ c.campaign_type }}</td><td>{{ c.status }}</td><td><button v-if="['active','scheduled'].includes(c.status)" class="btn btn-sm btn-outline-primary" @click="sendCampaign(c)">Send to selected customer IDs</button></td></tr><tr v-if="!campaigns.length"><td colspan="4" class="text-center text-muted">No campaigns.</td></tr></tbody></table></div></div>
        <div class="card mb-3"><div class="card-header fw-semibold">Customer marketing consent</div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>ID</th><th>Customer</th><th>Phone</th><th>Consent</th><th></th></tr></thead><tbody><tr v-for="c in lookups.customers" :key="c.id"><td>{{ c.id }}</td><td>{{ c.name }}</td><td>{{ c.phone||'—' }}</td><td>{{ c.marketing_opt_in ? 'Opted in' : 'Opted out' }}</td><td class="text-end"><button class="btn btn-sm" :class="c.marketing_opt_in?'btn-outline-danger':'btn-outline-primary'" @click="setMarketingConsent(c)">{{ c.marketing_opt_in ? 'Withdraw' : 'Record opt-in' }}</button></td></tr></tbody></table></div></div>
        <div class="card"><div class="card-header fw-semibold">Refill reminders</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Customer</th><th>Medicine</th><th>Reminder date</th><th>Status</th></tr></thead><tbody><tr v-for="r in reminders" :key="r.id"><td>{{ r.customer_name }}</td><td>{{ r.medicine_name }}</td><td>{{ r.remind_on }}</td><td>{{ r.status }}</td></tr><tr v-if="!reminders.length"><td colspan="4" class="text-center text-muted">No reminders.</td></tr></tbody></table></div></div>
      </div>
    </section>

    <!-- 5.4 analytics -->
    <section v-else-if="activeTab==='analytics'" class="card">
      <div class="card-header d-flex flex-wrap justify-content-between align-items-center gap-2"><div class="fw-semibold">Demand & profit forecast</div><div class="d-flex gap-2"><select v-model.number="forecastDays" class="form-select form-select-sm"><option :value="14">14 days</option><option :value="30">30 days</option><option :value="60">60 days</option><option :value="90">90 days</option></select><button class="btn btn-sm btn-primary" @click="runForecast">Generate forecast</button><button class="btn btn-sm btn-outline-secondary" @click="saveForecast">Save snapshot</button></div></div>
      <div class="card-body"><div class="alert alert-info py-2 small">Forecast uses average daily sales over the selected historical window. It is an operational estimate, not a guaranteed prediction.</div><h6 class="mt-3">Monthly seasonality / sales history</h6><div class="table-responsive mb-3"><table class="table table-sm"><thead><tr><th>Month</th><th>Invoices</th><th>Revenue</th><th>Collected</th></tr></thead><tbody><tr v-for="m in seasonalityRows" :key="m.year+'-'+m.month"><td>{{ m.year }}-{{ String(m.month).padStart(2,'0') }}</td><td>{{ m.invoices }}</td><td>{{ money(m.revenue) }}</td><td>{{ money(m.collected) }}</td></tr><tr v-if="!seasonalityRows.length"><td colspan="4" class="text-muted text-center">No historical sales data.</td></tr></tbody></table></div><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Medicine</th><th>Daily avg.</th><th>Forecast qty</th><th>Current stock</th><th>Suggested purchase</th><th>Forecast revenue</th><th>Gross profit</th></tr></thead><tbody><tr v-for="r in forecastRows" :key="r.medicine_id"><td>{{ r.medicine_name }}</td><td>{{ r.historical_daily_average }}</td><td>{{ r.forecast_quantity }}</td><td>{{ r.current_sellable_stock }}</td><td><span class="fw-semibold" :class="r.suggested_purchase_qty?'text-danger':''">{{ r.suggested_purchase_qty }}</span></td><td>{{ money(r.forecast_revenue) }}</td><td>{{ money(r.forecast_gross_profit) }}</td></tr><tr v-if="!forecastRows.length"><td colspan="7" class="text-center text-muted py-4">Generate a forecast to view recommendations.</td></tr></tbody></table></div></div>
    </section>

    <div v-if="loading" class="text-muted small mt-3"><span class="spinner-border spinner-border-sm me-2"></span>Loading Stage 5 data…</div>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue';
import { useRoute } from 'vue-router';
import api from '../api';

const route = useRoute();
const activeTab = ref(route.query.tab || 'procurement');
const loading = ref(false); const saving = ref(false);
const tabs = [
  {id:'procurement',label:'Supplier Quotations'},{id:'warehouse',label:'Warehouse & Stock Count'},{id:'healthcare',label:'Facilities & Refills'},
  {id:'insurance',label:'Insurance Eligibility'},{id:'compliance',label:'Recalls & Controlled Drugs'},{id:'engagement',label:'Campaigns & Refill Reminders'},{id:'analytics',label:'Demand Forecast'},
];
const summaryCards = [
  {key:'quotes_pending',label:'Quotes pending'},{key:'stock_counts_open',label:'Open stock counts'},{key:'refills_pending',label:'Refills pending'},
  {key:'open_recalls',label:'Open recalls'},{key:'controlled_medicines',label:'Controlled medicines'},{key:'eligible_reminders',label:'Due reminders'},
];
const overview=reactive({});
const lookups=reactive({suppliers:[],medicines:[],batches:[],customers:[],insurance_providers:[],insurance_plans:[]});
const quotations=ref([]), quoteComparisons=ref([]), locations=ref([]), stockCounts=ref([]), facilities=ref([]), refills=ref([]), eligibilityRows=ref([]), controlledRows=ref([]), recalls=ref([]), recallRows=ref([]), campaigns=ref([]), reminders=ref([]), forecastRows=ref([]);
const quote=reactive({supplier_id:'',medicine_id:'',quantity:1,unit_price:0,tax_percent:0,lead_days:0,valid_until:''});
const location=reactive({code:'',name:'',location_type:'bin'}); const allocation=reactive({batch_id:'',location_id:'',quantity:0}); const count=reactive({batch_id:'',counted_quantity:0});
const facility=reactive({name:'',facility_type:'hospital',registration_no:'',contact_person:'',phone:'',email:'',address:''}); const refillRequest=reactive({prescription_id:'',medicine_id:'',requested_quantity:1,customer_note:''});
const controlled=reactive({medicine_id:'',batch_id:'',transaction_type:'dispense',quantity_change:-1,reason:''});
const recall=reactive({source:'',severity:'warning',reason:'',issued_on:new Date().toISOString().slice(0,10),medicine_id:'',batch_id:''});
const eligibility=reactive({provider_id:'',plan_id:'',customer_id:'',member_no:'',result:'manual_review',notes:''});
const claimEvent=reactive({claim_id:'',event:'payer_update',external_reference:'',amount:'',notes:''});
const campaign=reactive({name:'',campaign_type:'general',message:'',status:'draft'}); const campaignCustomerIds=ref('');
const reminder=reactive({customer_id:'',medicine_id:'',last_dispensed_on:new Date().toISOString().slice(0,10),remind_on:''});
const forecastDays=ref(30); const seasonalityRows=ref([]);
const money=(value)=>new Intl.NumberFormat('en-PK',{style:'currency',currency:'PKR',maximumFractionDigits:2}).format(Number(value||0));
const list=(response)=>response?.data?.data ?? response?.data ?? [];

async function loadAll(){
  loading.value=true;
  try{
    const [o,l,q,qc,loc,sc,fac,rf,el,cr,rec,ri,cam,rem]=await Promise.all([
      api.get('/stage5/overview'),api.get('/stage5/lookups'),api.get('/stage5/quotations'),api.get('/stage5/quotations/comparison'),api.get('/stage5/warehouse/locations'),api.get('/stage5/warehouse/counts'),
      api.get('/stage5/facilities'),api.get('/stage5/refills'),api.get('/stage5/insurance/eligibility'),api.get('/stage5/compliance/controlled-register'),api.get('/stage5/compliance/recalls'),api.get('/stage5/compliance/recall-items'),api.get('/stage5/campaigns'),api.get('/stage5/reminders'),
    ]);
    Object.assign(overview,o.data); Object.assign(lookups,l.data); quotations.value=list(q); quoteComparisons.value=list(qc); locations.value=list(loc); stockCounts.value=list(sc); facilities.value=list(fac); refills.value=list(rf); eligibilityRows.value=list(el); controlledRows.value=list(cr); recalls.value=list(rec); recallRows.value=list(ri); campaigns.value=list(cam); reminders.value=list(rem);
  }catch(e){ /* API interceptor displays the useful error */ } finally {loading.value=false;}
}
async function done(promise){saving.value=true;try{await promise;await loadAll();return true;}catch(e){return false;}finally{saving.value=false;}}
async function createQuotation(){await done(api.post('/stage5/quotations',{supplier_id:quote.supplier_id,quote_date:new Date().toISOString().slice(0,10),valid_until:quote.valid_until||null,items:[{medicine_id:quote.medicine_id,quantity:quote.quantity,unit_price:quote.unit_price,tax_percent:quote.tax_percent,lead_days:quote.lead_days}]}));}
async function reviewQuote(q,decision){if(!confirm(`${decision} quotation ${q.quote_no}?`))return;await done(api.post(`/stage5/quotations/${q.id}/review`,{decision}));}
async function convertQuote(q){if(!confirm(`Convert ${q.quote_no} to a draft purchase order?`))return;await done(api.post(`/stage5/quotations/${q.id}/convert`));}
async function createLocation(){await done(api.post('/stage5/warehouse/locations',location));Object.assign(location,{code:'',name:'',location_type:'bin'});}
async function allocateBatch(){await done(api.post('/stage5/warehouse/allocate',allocation));}
async function createStockCount(){await done(api.post('/stage5/warehouse/counts',{items:[{batch_id:count.batch_id,counted_quantity:count.counted_quantity}]}));}
async function reviewCount(c,decision){if(!confirm(`${decision} stock count ${c.count_no}? Approval changes batch quantities and stock ledger.`))return;await done(api.post(`/stage5/warehouse/counts/${c.id}/review`,{decision}));}
async function saveFacility(){await done(api.post('/stage5/facilities',facility));Object.assign(facility,{name:'',facility_type:'hospital',registration_no:'',contact_person:'',phone:'',email:'',address:''});}
async function createFacilityToken(f){if(!confirm(`Create a one-time API token for ${f.name}?`))return;try{const r=await api.post(`/stage5/facilities/${f.id}/api-token`);alert(`Copy this token now. It will not be shown again:\n\n${r.data.token}`);}catch(e){}}
async function submitRefill(){await done(api.post('/stage5/refills',refillRequest));Object.assign(refillRequest,{prescription_id:'',medicine_id:'',requested_quantity:1,customer_note:''});}
async function reviewRefill(r,decision){if(!confirm(`${decision} refill ${r.request_no}?`))return;await done(api.post(`/stage5/refills/${r.id}/review`,{decision}));}
async function checkEligibility(){await done(api.post('/stage5/insurance/eligibility',eligibility));}
async function recordClaimEvent(){const id=claimEvent.claim_id;await done(api.post(`/stage5/insurance/claims/${id}/events`,{event:claimEvent.event,external_reference:claimEvent.external_reference,amount:claimEvent.amount||null,notes:claimEvent.notes}));}
async function recordControlled(){await done(api.post('/stage5/compliance/controlled-register',controlled));}
async function setControlled(m){const enabled=!m.requires_controlled_tracking;if(!confirm(`${enabled?'Enable':'Disable'} controlled tracking for ${m.name}?`))return;await done(api.patch(`/stage5/compliance/medicines/${m.id}/controlled`,{enabled}));}
async function releaseRecallItem(i){if(!confirm(`Release quarantined batch ${i.batch_no||i.batch_id}? Only release after the recall authority confirms it is safe.`))return;const reason=prompt('Enter release authorization / reason:');if(!reason)return;await done(api.post(`/stage5/compliance/recall-items/${i.id}/release`,{release_reason:reason}));}
async function createRecall(){await done(api.post('/stage5/compliance/recalls',{...recall,items:[{medicine_id:recall.medicine_id,batch_id:recall.batch_id||null,affected_quantity:0}]}));}
async function closeRecall(r){if(!confirm(`Close recall ${r.recall_no}? Batch quarantine remains until released.`))return;await done(api.post(`/stage5/compliance/recalls/${r.id}/close`));}
async function saveCampaign(){await done(api.post('/stage5/campaigns',campaign));Object.assign(campaign,{name:'',campaign_type:'general',message:'',status:'draft'});}
async function setMarketingConsent(c){const opted_in=!Boolean(c.marketing_opt_in);if(!confirm(`${opted_in?'Record opt-in':'Withdraw marketing consent'} for ${c.name}?`))return;await done(api.patch(`/stage5/customers/${c.id}/marketing-consent`,{opted_in}));}
async function sendCampaign(c){const ids=campaignCustomerIds.value.split(',').map(x=>Number(x.trim())).filter(x=>Number.isInteger(x)&&x>0);if(!ids.length){alert('Enter one or more customer IDs in the prompt.');return;}if(!confirm(`Send campaign ${c.name} to ${ids.length} selected customer(s) using the approved WhatsApp template?`))return;await done(api.post(`/stage5/campaigns/${c.id}/send`,{customer_ids:ids}));}
async function createReminder(){await done(api.post('/stage5/reminders',reminder));}
async function runForecast(){try{const [r,s]=await Promise.all([api.get('/stage5/analytics/forecast',{params:{forecast_days:forecastDays.value}}),api.get('/stage5/analytics/seasonality',{params:{months:24}})]);forecastRows.value=r.data.items||[];seasonalityRows.value=s.data.data||[];}catch(e){}}
async function saveForecast(){if(!forecastRows.value.length){await runForecast();if(!forecastRows.value.length)return;}const start=new Date();start.setDate(start.getDate()+1);const end=new Date(start);end.setDate(end.getDate()+forecastDays.value-1);await done(api.post('/stage5/analytics/forecast/save',{period_start:start.toISOString().slice(0,10),period_end:end.toISOString().slice(0,10),forecast_type:'demand'}));}
onMounted(loadAll);
</script>

<style scoped>
.stage-tabs{scrollbar-width:thin}.stage-tabs .nav-link{font-size:.875rem}.table th{font-size:.78rem;text-transform:uppercase;letter-spacing:.02em;color:var(--bs-secondary-color);white-space:nowrap}.card{border-color:var(--bs-border-color)}
</style>
